with r as (select *, row_number() over (partition by player_api_id order by date desc, id desc) rn from player_attributes)
select round(100.0*sum(case when attacking_work_rate='low' then 1 else 0 end)/count(*),1) as pct
from r where rn=1 and preferred_foot='left' and attacking_work_rate in ('low','medium','high')

